async def get_per_second_income(user_id: int) -> tuple[float, float]:
    bonus = await get_status_bonus(user_id)
    multiplier = 1 + bonus

    # клановый бонус
    clan = await get_clan(user_id)
    if clan:
        clan_bonus = clan[4] or 0.0
        multiplier *= (1 + clan_bonus)

    # бонус питомца
    pet_coins = await get_pet_bonus(user_id, "income_coins")
    pet_gems = await get_pet_bonus(user_id, "income_gems")
    # бонус титула
    title_coins = await get_title_bonus(user_id, "income_coins")
    title_gems = await get_title_bonus(user_id, "income_gems")

    # бонус престижа, коллекции и сетов
    prestige_bonus = await get_prestige_bonus(user_id)
    collection_bonus = await get_collection_bonus(user_id)
    set_bonus = await get_set_bonus(user_id)

    multiplier_coins = multiplier * (
        1 + pet_coins + title_coins + prestige_bonus + collection_bonus + set_bonus
    )
    multiplier_gems = multiplier * (
        1 + pet_gems + title_gems + prestige_bonus + collection_bonus + set_bonus
    )

    async with bot.db.execute("""
        SELECT inv.stars, i.income_per_hour, i.income_gems_per_hour
        FROM inventory inv
        JOIN items i ON inv.item_id = i.id
        WHERE inv.user_id = ? AND inv.location = 'profile'
    """, (user_id,)) as c:
        rows = await c.fetchall()

    per_sec_coins_raw = 0.0
    per_sec_gems_raw = 0.0
    for stars, inc_coins, inc_gems in rows:
        star_mult = 1 + STAR_BONUS.get(stars, 0)
        per_sec_coins_raw += inc_coins * star_mult
        per_sec_gems_raw += inc_gems * star_mult

    return per_sec_coins_raw * multiplier_coins, per_sec_gems_raw * multiplier_gems




async def calculate_passive_income(user_id: int, guild_id: int = None):
    async with bot.db.execute(
        "SELECT last_collected, last_gem_collected FROM players WHERE user_id = ?",
        (user_id,)
    ) as c:
        row = await c.fetchone()
    if not row:
        return 0, 0
    last_coins_str, last_gems_str = row

    # Все бонусы (статус + клан + питомцы) уже учтены в get_per_second_income
    per_sec_coins, per_sec_gems = await get_per_second_income(user_id)

    now = datetime.datetime.now()

    coins = 0
    if per_sec_coins > 0:
        last = datetime.datetime.fromisoformat(last_coins_str)
        seconds = (now - last).total_seconds()
        coins = int(effective_offline_seconds(seconds) * per_sec_coins)

    gems = 0
    if per_sec_gems > 0:
        last = datetime.datetime.fromisoformat(last_gems_str)
        seconds = (now - last).total_seconds()
        gems = int(effective_offline_seconds(seconds) * per_sec_gems)

    return coins, gems


async def calculate_full_passive_income(user_id: int) -> tuple[int, int]:
    """Полный доход без офлайн-штрафа и без потолков.

    Используется автосборщиком.
    """
    async with bot.db.execute(
        "SELECT last_collected, last_gem_collected FROM players WHERE user_id = ?",
        (user_id,),
    ) as c:
        row = await c.fetchone()
    if not row:
        return 0, 0

    last_coins_str, last_gems_str = row

    per_sec_coins, per_sec_gems = await get_per_second_income(user_id)
    now = datetime.datetime.now()

    coins = 0
    last_coins = _parse_db_time(last_coins_str)
    if per_sec_coins > 0 and last_coins:
        seconds = min(
            OFFLINE_MAX_HOURS * 3600,
            max(0.0, (now - last_coins).total_seconds()),
        )
        coins = int(seconds * per_sec_coins)

    gems = 0
    last_gems = _parse_db_time(last_gems_str)
    if per_sec_gems > 0 and last_gems:
        seconds = min(
            OFFLINE_MAX_HOURS * 3600,
            max(0.0, (now - last_gems).total_seconds()),
        )
        gems = int(seconds * per_sec_gems)

    return coins, gems


async def collect_income(user_id: int, guild_id: int = None):
    async with db_transaction():
        coins_earned, gems_earned = await calculate_passive_income(user_id, guild_id)
        if coins_earned <= 0 and gems_earned <= 0:
            return 0, 0

        now_iso = datetime.datetime.now().isoformat()
        if coins_earned > 0:
            await bot.db.execute(
                "UPDATE players SET coins = coins + ?, "
                "total_coins_earned = total_coins_earned + ?, "
                "lifetime_production = lifetime_production + ?, "
                "last_collected = ? WHERE user_id = ?",
                (coins_earned, coins_earned, coins_earned, now_iso, user_id)
            )
        if gems_earned > 0:
            await bot.db.execute(
                "UPDATE players SET gems = gems + ?, "
                "total_gems_earned = total_gems_earned + ?, "
                "last_gem_collected = ? WHERE user_id = ?",
                (gems_earned, gems_earned, now_iso, user_id)
            )

        # ежедневные задания
        await update_quest_progress(user_id, "collect_income")
        await update_quest_progress(user_id, "collect_income_3")

        # сюжетные квесты
        await update_story_quests(user_id, "coins", coins_earned)
        await update_story_quests(user_id, "collect_income", 1)

        # достижения за накопление монет/гемов
        await check_achievements(user_id)

        return coins_earned, gems_earned

async def get_menu_welcome_notification(user_id: int, guild_id: int = None) -> str | None:
    """Проверяет, сколько прошло времени с последнего сбора, и возвращает текст уведомления."""
    async with bot.db.execute(
        "SELECT last_collected FROM players WHERE user_id = ?", (user_id,)
    ) as c:
        row = await c.fetchone()
    
    if not row or not row[0]:
        return None
        
    last_collected = datetime.datetime.fromisoformat(row[0])
    now = datetime.datetime.now()
    seconds_passed = (now - last_collected).total_seconds()
    
    # Если прошло меньше 30 минут, уведомление не нужно (чтобы не спамить)
    if seconds_passed < 1800:
        return None
        
    # Считаем доход (не собирая его, просто для отображения)
    coins_earned, gems_earned = await calculate_passive_income(user_id, guild_id)
    
    if coins_earned == 0 and gems_earned == 0:
        return None
        
    # Форматируем время
    hours = int(seconds_passed // 3600)
    minutes = int((seconds_passed % 3600) // 60)
    
    if hours > 0:
        time_str = f"{hours} ч {minutes} мин"
    else:
        time_str = f"{minutes} мин"
        
    coin_emoji = str(BOT_BTN_EMOJIS.get("_coin", "🪙"))
    gem_emoji = str(BOT_BTN_EMOJIS.get("_gem", "💎"))
    
    parts = []
    if coins_earned > 0:
        parts.append(f"{coin_emoji} {coins_earned}")
    if gems_earned > 0:
        parts.append(f"{gem_emoji} {gems_earned}")
        
    income_str = " и ".join(parts)
    
    return (
        f"👋 С возвращением! Пока тебя не было ({time_str}), твои генераторы заработали:\n\n"
        f"**{income_str}**\n\n"
        f"*(Доход уже добавлен в кошелёк, он отображён в меню ниже).*"
    )


async def deny_content_edit(interaction: discord.Interaction) -> bool:
    """True, если правку контента нужно отклонить."""
    if await is_global_owner(interaction):
        return False
    await interaction.response.send_message(
        "❌ Контент может менять только владелец бота.",
        ephemeral=True,
    )
    return True


async def delete_message_later(message, delay: int):
    """Удаляет публичное сообщение бота через delay секунд."""
    await asyncio.sleep(delay)
    try:
        await message.delete()
    except (discord.NotFound, discord.Forbidden, discord.HTTPException):
        pass


def title_effect_bonus(title_name: str | None, effect_type: str) -> float:
    """Бонус титула по названию без обращения к БД."""
    if not title_name:
        return 0.0
    for title_id, (name, _req) in TITLES.items():
        if name == title_name:
            btype, bval = TITLE_BONUSES.get(title_id, (None, 0.0))
            return bval if btype == effect_type else 0.0
    return 0.0


async def get_title_bonus(user_id: int, effect_type: str) -> float:
    """Бонус от активного титула игрока для указанного эффекта."""
    async with bot.db.execute(
        "SELECT title FROM players WHERE user_id = ?", (user_id,)
    ) as c:
        row = await c.fetchone()
    if not row:
        return 0.0
    return title_effect_bonus(row[0], effect_type)

async def get_total_bonus_line(user_id: int) -> str:
    """Возвращает эффективные множители дохода отдельно для монет и гемов."""
    status_bonus = await get_status_bonus(user_id)

    clan_bonus = 0.0
    clan = await get_clan(user_id)
    if clan:
        clan_bonus = clan[4] or 0.0

    pet_coins = await get_pet_bonus(user_id, "income_coins")
    pet_gems = await get_pet_bonus(user_id, "income_gems")
    title_coins = await get_title_bonus(user_id, "income_coins")
    title_gems = await get_title_bonus(user_id, "income_gems")
    prestige_bonus = await get_prestige_bonus(user_id)
    collection_bonus = await get_collection_bonus(user_id)
    set_bonus = await get_set_bonus(user_id)

    mult_coins = (1 + status_bonus) * (1 + clan_bonus) * (
        1 + pet_coins + title_coins + prestige_bonus + collection_bonus + set_bonus
    )
    mult_gems = (1 + status_bonus) * (1 + clan_bonus) * (
        1 + pet_gems + title_gems + prestige_bonus + collection_bonus + set_bonus
    )
    coin_pct = int((mult_coins - 1) * 100)
    gem_pct = int((mult_gems - 1) * 100)

    parts = []
    if status_bonus > 0:
        parts.append(f"статус +{int(status_bonus*100)}%")
    if clan_bonus > 0:
        parts.append(f"клан +{int(clan_bonus*100)}%")
    if pet_coins or pet_gems:
        parts.append(f"питомец +{int(pet_coins*100)}%/+{int(pet_gems*100)}%")
    if title_coins or title_gems:
        parts.append(f"титул +{int(title_coins*100)}%/+{int(title_gems*100)}%")
    if prestige_bonus > 0:
        parts.append(f"престиж +{int(prestige_bonus*100)}%")
    if collection_bonus > 0:
        parts.append(f"коллекция +{int(collection_bonus*100)}%")
    if set_bonus > 0:
        parts.append(f"сеты +{int(set_bonus*100)}%")

    suffix = f" ({', '.join(parts)})" if parts else " (нет бонусов)"
    return f"**Монеты: +{coin_pct}%** | **Гемы: +{gem_pct}%**{suffix}"

async def get_total_bonus_percent(user_id: int) -> int:
    """Возвращает эффективный бонус к доходу монет в процентах."""
    status_bonus = await get_status_bonus(user_id)

    # клан
    clan_bonus = 0.0
    clan = await get_clan(user_id)
    if clan:
        clan_bonus = clan[4] or 0.0

    # питомец, титул и престиж для монет
    pet_coins = await get_pet_bonus(user_id, "income_coins")
    title_coins = await get_title_bonus(user_id, "income_coins")
    prestige_bonus = await get_prestige_bonus(user_id)
    collection_bonus = await get_collection_bonus(user_id)
    set_bonus = await get_set_bonus(user_id)

    mult_coins = (1 + status_bonus) * (1 + clan_bonus) * (
        1 + pet_coins + title_coins + prestige_bonus + collection_bonus + set_bonus
    )
    return int((mult_coins - 1) * 100)


