async def get_prestige_bonus(user_id: int) -> float:
    points = await get_prestige_points(user_id)
    return min(points * PRESTIGE_BONUS_PER_POINT, PRESTIGE_BONUS_CAP)


async def grant_status_role(
    interaction: discord.Interaction, user_id: int, status_id: str
):
    guild = getattr(interaction, "guild", None)
    guild_id = getattr(interaction, "guild_id", None)
    if not guild or not guild_id:
        return
    settings = await get_settings(guild_id)
    role_id = settings.get("status_roles", {}).get(status_id)
    if not role_id:
        return
    member = guild.get_member(user_id)
    role = guild.get_role(role_id)
    if not member or not role:
        return
    try:
        await member.add_roles(
            role, reason=f"Статус {STATUS_NAMES.get(status_id, status_id)}"
        )
    except discord.HTTPException:
        pass


async def remove_status_role(user_id: int, status_id: str):
    for guild in getattr(bot, "guilds", []):
        try:
            settings = await get_settings(guild.id)
            role_id = settings.get("status_roles", {}).get(status_id)
            if not role_id:
                continue
            member = guild.get_member(user_id)
            role = guild.get_role(role_id)
            if member and role:
                await member.remove_roles(role, reason="Временный статус истёк")
        except Exception:
            log.debug(
                "STATUS_EXPIRY: не удалось снять роль %s у %s",
                status_id,
                user_id,
            )


async def get_collection_count(user_id: int) -> int:
    async with bot.db.execute(
        "SELECT COUNT(*) FROM player_collection pc "
        "JOIN items i ON i.id = pc.item_id "
        "WHERE pc.user_id = ? AND i.id LIKE '%\\_gen' ESCAPE '\\'",
        (user_id,),
    ) as c:
        return (await c.fetchone())[0] or 0


async def get_collection_bonus(user_id: int) -> float:
    return (await get_collection_count(user_id)) * COLLECTION_BONUS_PER_ITEM


def prestige_required_total(points: int) -> int:
    """Сколько всего монет нужно для получения N очков престижа."""
    points = max(0, int(points))
    return (
        points * PRESTIGE_BASE_REQUIREMENT
        + PRESTIGE_STEP_REQUIREMENT * points * (points - 1) // 2
    )


