class GuideView(BaseView):
    def __init__(self, author_id: int, page: int = 0, timeout: int = 600):
        super().__init__(author_id, timeout)
        self.page = page

        items = list(GUIDE_SECTIONS.items())
        per_page = 5
        total_pages = (len(items) + per_page - 1) // per_page
        page = max(0, min(page, total_pages - 1))
        chunk = items[page*per_page:(page+1)*per_page]

        self.add_item(
            make_select(
                "Быстрый переход к разделу",
                [
                    discord.SelectOption(
                        label=label[:100],
                        value=key,
                        description=desc[:100],
                        emoji=parse_emoji_safe(
                            get_emoji(
                                GUIDE_SECTION_EMOJIS.get(
                                    key, "_guide"
                                )
                            )
                        ),
                    )
                    for key, (label, desc) in items
                ],
                self.select_section,
                row=0,
            )
        )

        for idx, (key, (label, _desc)) in enumerate(chunk):
            btn = discord.ui.Button(
                label=label[:80],
                emoji=get_emoji(GUIDE_SECTION_EMOJIS.get(key, "_guide")),
                style=discord.ButtonStyle.primary,
                row=1,
            )
            btn.callback = self._make_section_callback(key)
            self.add_item(btn)

        if total_pages > 1:
            prev = discord.ui.Button(label="Назад", emoji=get_emoji("_back"), style=discord.ButtonStyle.success, row=2)
            prev.callback = self.prev_page
            self.add_item(prev)
            nxt = discord.ui.Button(label="Вперёд", emoji=get_emoji("_forward"), style=discord.ButtonStyle.secondary, row=2)
            nxt.callback = self.next_page
            self.add_item(nxt)

        back = discord.ui.Button(
            label="В меню",
            emoji=get_emoji("_back"),
            style=discord.ButtonStyle.success,
            row=2
        )
        back.callback = self.btn_back
        self.add_item(back)

    async def select_section(self, interaction: discord.Interaction):
        key = interaction.data["values"][0]
        await self._make_section_callback(key)(interaction)

    def _make_section_callback(self, key: str):
        async def callback(interaction: discord.Interaction):
            await interaction.response.defer()
            embed, total_pages = await build_guide_section_page(key, 0)
            await interaction.edit_original_response(
                embed=embed,
                view=GuideSectionView(
                    self.author_id, key, 0, self.page, total_pages
                ),
            )
        return callback

    async def prev_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        new_page = max(0, self.page - 1)
        embed = BotEmbed(title="📖 Путеводитель", description="Выбери раздел:", color=0x3498db)
        await interaction.edit_original_response(embed=embed, view=GuideView(self.author_id, new_page))

    async def next_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        items = list(GUIDE_SECTIONS.items())
        total_pages = (len(items) + 5 - 1) // 5
        new_page = min(total_pages - 1, self.page + 1)
        embed = BotEmbed(title="📖 Путеводитель", description="Выбери раздел:", color=0x3498db)
        await interaction.edit_original_response(embed=embed, view=GuideView(self.author_id, new_page))

    async def btn_back(self, interaction: discord.Interaction):
        await interaction.response.defer()
        embed = await build_main_embed(interaction)
        await interaction.edit_original_response(embed=embed, view=MainMenuView(self.author_id))

