async def open_clan_invites(interaction: discord.Interaction, author_id: int):
    async with bot.db.execute("""
        SELECT ci.id, c.id, c.name
        FROM clan_invites ci
        JOIN clans c ON c.id = ci.clan_id
        WHERE ci.target_id = ?
        ORDER BY ci.created_at DESC
    """, (author_id,)) as c:
        rows = await c.fetchall()

    if not rows:
        return await interaction.followup.send("❌ У тебя нет приглашений.", ephemeral=True)

    visible = rows[:25]
    options = [
        discord.SelectOption(
            label=name[:100],
            value=f"{invite_id}:{clan_id}",
            description="Принять приглашение",
            emoji=get_emoji("_castle"),
        )
        for invite_id, clan_id, name in visible
    ]
    description = "Выбери клан, чтобы вступить."
    if len(rows) > 25:
        description += f"\nПоказаны первые 25 из {len(rows)} приглашений."
    embed = BotEmbed(
        title="📩 Приглашения в клан",
        description=description,
        color=0x3498db,
    )
    await interaction.edit_original_response(
        embed=embed, view=ClanInvitesView(author_id, options)
    )


class ClanInvitesView(SafeView):
    feature_key = "clans"
    def __init__(self, author_id: int, options: list[discord.SelectOption]):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.add_item(make_select("Выбери приглашение", options, self.select, row=0))
        back = discord.ui.Button(
            label="Назад", emoji=get_emoji("_back"), style=discord.ButtonStyle.success, row=1
        )
        back.callback = self.back
        self.add_item(back)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await self.check_owner(interaction)

    async def select(self, interaction: discord.Interaction):
        value = interaction.data["values"][0]
        invite_id_str, clan_id_str = value.split(":", 1)
        invite_id = int(invite_id_str)
        clan_id = int(clan_id_str)
        await interaction.response.defer()

        if await get_clan(self.author_id):
            return await interaction.followup.send("❌ Ты уже в клане.", ephemeral=True)

        try:
            async with db_transaction():
                async with bot.db.execute(
                    "SELECT name FROM clans WHERE id = ?", (clan_id,)
                ) as c:
                    clan_row = await c.fetchone()
                if not clan_row:
                    raise ValueError("Клан уже не существует.")
                capacity = await get_clan_capacity(clan_id)
                members = await get_clan_member_count(clan_id)
                if members >= capacity:
                    raise ValueError("Клан заполнен. Нужно расширить состав.")

                async with bot.db.execute(
                    "SELECT 1 FROM clan_invites WHERE id = ? AND target_id = ?",
                    (invite_id, self.author_id),
                ) as c:
                    if not await c.fetchone():
                        raise ValueError("Приглашение уже недействительно.")

                await bot.db.execute(
                    "INSERT INTO clan_members (user_id, clan_id, role) "
                    "VALUES (?, ?, 'member')",
                    (self.author_id, clan_id),
                )
                await bot.db.execute(
                    "DELETE FROM clan_invites WHERE target_id = ?", (self.author_id,)
                )
        except (ValueError, aiosqlite.IntegrityError) as e:
            msg = str(e) if isinstance(e, ValueError) else "Ты уже в клане."
            return await interaction.followup.send(f"❌ {msg}", ephemeral=True)

        await log_clan(clan_id, "join", f"<@{self.author_id}>")
        await update_story_quests(self.author_id, "clan_join", 1)

        clan = await get_clan(self.author_id)
        if clan:
            embed = await build_clan_embed(interaction, clan)
            await interaction.edit_original_response(
                embed=embed, view=ClanMenuView(self.author_id, clan[0])
            )

    async def back(self, interaction: discord.Interaction):
        await interaction.response.defer()
        embed = BotEmbed(
            title=f"{get_emoji('_clan')} Кланы",
            description="Ты не состоишь в клане.\nСоздай свой за **500 монет** или вступи в существующий.",
            color=0x3498db,
        )
        await interaction.edit_original_response(
            embed=embed, view=NoClanView(self.author_id)
        )


async def open_clan_browser(
    interaction: discord.Interaction,
    author_id: int,
    page: int = 0,
    query: str | None = None,
):
    embed, total_pages, chunk = await build_clan_browser_embed(page, query)
    options = [
        discord.SelectOption(
            label=f"{name} — {members} чел."[:100],
            value=str(clan_id),
            description=(
                f"Бонус +{int((bonus or 0) * 100)}% · "
                f"сундук {format_price(treasury or 0)}"
            )[:100],
            emoji=get_emoji("_castle"),
        )
        for clan_id, name, _leader, treasury, bonus, members in chunk
    ]
    await interaction.edit_original_response(
        embed=embed,
        view=ClanBrowserView(author_id, options, page, total_pages, query),
    )


async def open_clan_detail(
    interaction: discord.Interaction,
    author_id: int,
    clan_id: int,
    page: int = 0,
    query: str | None = None,
):
    async with bot.db.execute(
        "SELECT c.name, c.leader_id, c.treasury, c.bonus, COUNT(cm.user_id) "
        "FROM clans c LEFT JOIN clan_members cm ON cm.clan_id = c.id "
        "WHERE c.id = ? GROUP BY c.id",
        (clan_id,),
    ) as c:
        row = await c.fetchone()
    if not row:
        return await interaction.followup.send("❌ Клан не найден.", ephemeral=True)
    name, leader_id, treasury, bonus, members = row
    async with bot.db.execute(
        "SELECT status FROM clan_applications WHERE clan_id = ? AND user_id = ?",
        (clan_id, author_id),
    ) as c:
        app_row = await c.fetchone()
    status = app_row[0] if app_row else None
    status_text = {
        "pending": "заявка на рассмотрении",
        "accepted": "ты принят",
        "declined": "заявка отклонена",
    }.get(status, "заявки нет")
    embed = BotEmbed(
        title=f"🏰 {name}",
        description=(
            f"Лидер: <@{leader_id}>\n"
            f"Участников: **{members}**\n"
            f"Сундук: 🪙 {format_price(treasury or 0)}\n"
            f"Бонус к доходу: **+{int((bonus or 0) * 100)}%**\n"
            f"Твой статус: **{status_text}**"
        ),
        color=0x3498db,
    )
    await interaction.edit_original_response(
        embed=embed,
        view=ClanBrowserDetailView(
            author_id, clan_id, page, query,
            can_apply=status not in ("pending", "accepted"),
        ),
    )


