class DuelChallengeView(SafeView):
    feature_key = "pvp"
    def __init__(self, challenger_id: int, opponent_id: int, bet: int, mode: str):
        super().__init__(timeout=DUEL_CHALLENGE_TIMEOUT)
        self.challenger_id = challenger_id
        self.opponent_id = opponent_id
        self.bet = bet
        self.mode = mode
        self.resolved = False
        self.message = None
        self._delete_task = None

    def _schedule_delete(self, delay: int):
        if not self.message:
            return
        if self._delete_task and not self._delete_task.done():
            return
        self._delete_task = asyncio.create_task(self._delete_later(delay))

    async def _delete_later(self, delay: int):
        await asyncio.sleep(delay)
        try:
            await self.message.delete()
        except (discord.NotFound, discord.Forbidden, discord.HTTPException):
            pass

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.opponent_id:
            await interaction.response.send_message(
                "❌ Этот вызов не для тебя.", ephemeral=True
            )
            return False
        return True

    @discord.ui.button(label="Принять", emoji=get_emoji("_approve"), style=discord.ButtonStyle.success)
    async def accept(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        if self.resolved:
            return
        self.resolved = True

        ok, msg = await resolve_duel(
            self.challenger_id,
            self.opponent_id,
            self.bet,
            self.mode,
            interaction.guild_id,
        )
        embed = BotEmbed(
            title="Результат дуэли",
            description=msg,
            color=0x2ecc71 if ok else 0xe74c3c,
        )
        try:
            await interaction.message.edit(embed=embed, view=None)
        except discord.HTTPException:
            pass
        self._schedule_delete(DUEL_CHALLENGE_DELETE_SECONDS)

    @discord.ui.button(label="Отклонить", emoji=get_emoji("_cancel"), style=discord.ButtonStyle.secondary)
    async def decline(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        if self.resolved:
            return
        self.resolved = True
        embed = BotEmbed(
            title="Дуэль отклонена",
            description=f"<@{self.opponent_id}> отклонил вызов.",
            color=0x808080,
        )
        try:
            await interaction.message.edit(embed=embed, view=None)
        except discord.HTTPException:
            pass
        self._schedule_delete(DUEL_CHALLENGE_DECLINE_SECONDS)

    async def on_timeout(self):
        if self.resolved:
            return
        self.resolved = True
        if self.message:
            try:
                embed = BotEmbed(
                    title="Вызов истёк",
                    description="Противник не ответил за 2 минуты.",
                    color=0x808080,
                )
                await self.message.edit(embed=embed, view=None)
                self._schedule_delete(DUEL_CHALLENGE_DECLINE_SECONDS)
            except discord.HTTPException:
                pass


