async def open_pets_shop(
    interaction: discord.Interaction, author_id: int, return_to: str = "shop"
):
    async with bot.db.execute("SELECT gems FROM players WHERE user_id = ?", (author_id,)) as c:
        gems = (await c.fetchone())[0]

    async with bot.db.execute("SELECT pet_id FROM user_pets_v2 WHERE user_id = ?", (author_id,)) as c:
        owned = {r[0] for r in await c.fetchall()}

    options = []
    for pid, pt in PET_TYPES.items():
        if pid in owned:
            continue
            
        # Парсим строку <:cat:id> в объект PartialEmoji
        emoji_obj = parse_emoji_safe(pt["emoji"]) 
        if not emoji_obj:
            emoji_obj = "🐾" # Фолбэк, если что-то пошло не так

        options.append(discord.SelectOption(
            label=(
                f"{pt['name']} — {pt['price_gems']} "
                f"{plural_ru(pt['price_gems'], 'гем', 'гема', 'гемов')}"
            )[:100],
            value=pid, 
            description=pt["desc"][:100],
            emoji=emoji_obj
        ))

    if not options:
        embed = BotEmbed(
            title="🛒 Магазин питомцев",
            description="Ты уже купил всех питомцев! 🎉\nСмени активного в меню «Питомцы».",
            color=0x9b59b6
        )
        back = discord.ui.Button(label="Назад", emoji=BOT_BTN_EMOJIS.get("_back", "◀️"), style=discord.ButtonStyle.success)
        async def _back(i: discord.Interaction):
            await i.response.defer()
            embed2 = await build_pets_embed(i)
            await i.edit_original_response(
                embed=embed2, view=PetsView(author_id, return_to=return_to)
            )
        back.callback = _back
        view = SafeView()
        view.add_item(back)
        await interaction.edit_original_response(embed=embed, view=view)
        return

    embed = BotEmbed(
        title=f"{BOT_BTN_EMOJIS.get('_pets', '🐾')} Магазин питомцев",
        description=f"У тебя {BOT_BTN_EMOJIS.get('_gem', '💎')} {gems}. Выбери питомца:",
        color=0x9b59b6
    )
    await interaction.edit_original_response(
        embed=embed, view=PetsShopView(author_id, options, return_to)
    )


class PetsShopView(SafeView):
    feature_key = "pets"
    home_row = 4
    def __init__(self, author_id: int, options: list, return_to: str = "shop"):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.return_to = return_to
        self.add_item(make_select("Выбери питомца", options, self.select, row=0))
        back = discord.ui.Button(label="Назад", emoji=get_emoji("_back"), style=discord.ButtonStyle.success, row=1)
        back.callback = self.back
        self.add_item(back)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await self.check_owner(interaction)

    async def select(self, interaction: discord.Interaction):
        pet_id = interaction.data["values"][0]
        await interaction.response.defer()
        ptype = PET_TYPES.get(pet_id)
        if not ptype:
            await interaction.followup.send("❌ Питомец не найден.", ephemeral=True)
            return

        try:
            async with db_transaction():
                async with bot.db.execute(
                    "SELECT 1 FROM user_pets_v2 WHERE user_id = ? AND pet_id = ?",
                    (self.author_id, pet_id),
                ) as c:
                    if await c.fetchone():
                        raise ValueError("Этот питомец уже есть.")

                async with bot.db.execute(
                    "SELECT gems FROM players WHERE user_id = ?", (self.author_id,)
                ) as c:
                    gems_row = await c.fetchone()
                gems = (gems_row[0] if gems_row else 0) or 0
                if gems < ptype["price_gems"]:
                    raise ValueError(f"Нужно 💎 {ptype['price_gems']}, у тебя {gems}.")

                cur = await bot.db.execute(
                    "UPDATE players SET gems = gems - ? "
                    "WHERE user_id = ? AND gems >= ?",
                    (ptype["price_gems"], self.author_id, ptype["price_gems"]),
                )
                if cur.rowcount == 0:
                    raise ValueError("Не хватает гемов (баланс изменился).")

                await bot.db.execute(
                    "INSERT INTO user_pets_v2 (user_id, pet_id, level, last_fed) "
                    "VALUES (?, ?, 1, NULL)",
                    (self.author_id, pet_id),
                )
                async with bot.db.execute(
                    "SELECT active_pet FROM players WHERE user_id = ?", (self.author_id,)
                ) as c:
                    active_row = await c.fetchone()
                active = (active_row[0] if active_row else None)
                if not active:
                    await bot.db.execute(
                        "UPDATE players SET active_pet = ? WHERE user_id = ?",
                        (pet_id, self.author_id),
                    )
        except ValueError as e:
            return await interaction.followup.send(f"❌ {e}", ephemeral=True)
        await interaction.followup.send(
            f"✅ Куплен {ptype['emoji']} **{ptype['name']}** за 💎 {ptype['price_gems']}!",
            ephemeral=True
        )
        await update_story_quests(self.author_id, "pet_buy", 1)

    async def back(self, interaction: discord.Interaction):
        await interaction.response.defer()
        embed = await build_pets_embed(interaction)
        await interaction.edit_original_response(
            embed=embed, view=PetsView(self.author_id, self.return_to)
        )


class TitlesView(SafeView):
    home_row = 4
    def __init__(self, author_id: int, options, page: int, total_pages: int, return_to: str = "main"):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.page = page
        self.total_pages = total_pages
        self.return_to = return_to
        self.add_item(make_select("Выбери титул", options, self.select, row=0))
        if total_pages > 1:
            p = discord.ui.Button(label="Стр.", emoji=get_emoji("_back"), style=discord.ButtonStyle.secondary, row=1)
            p.callback = self.prev; self.add_item(p)
            n = discord.ui.Button(label="Стр.", emoji=get_emoji("_forward"), style=discord.ButtonStyle.secondary, row=1)
            n.callback = self.next; self.add_item(n)
        b = discord.ui.Button(label="Назад", emoji=get_emoji("_back"), style=discord.ButtonStyle.success, row=2)
        b.callback = self.back; self.add_item(b)

    async def interaction_check(self, interaction):
        return await self.check_owner(interaction)

    async def select(self, interaction: discord.Interaction):
        tid = interaction.data["values"][0]
        await interaction.response.defer()
        unlocked = await get_unlocked_titles(self.author_id)
        if tid not in unlocked:
            await interaction.followup.send("❌ Титул ещё не открыт.", ephemeral=True)
            return
        name = TITLES[tid][0]
        await bot.db.execute("UPDATE players SET title = ? WHERE user_id = ?", (name, self.author_id))
        await commit_if_needed()
        await interaction.followup.send(f"✅ Титул изменён на **{name}**.", ephemeral=True)

    async def prev(self, i):
        await i.response.defer()
        await open_titles_view(i, self.author_id, self.page-1, self.return_to)

    async def next(self, i):
        await i.response.defer()
        await open_titles_view(i, self.author_id, self.page+1, self.return_to)

    async def back(self, i):
        await i.response.defer()
        if self.return_to == "profile":
            embed = await build_user_profile_embed(i)
            await i.edit_original_response(
                embed=embed, view=UserProfileView(self.author_id)
            )
        elif self.return_to == "hub":
            embed = BotEmbed(
                title="🎨 Кастомизация",
                description="Выбери раздел: титулы, дейли, косметика, сюжетные квесты.",
                color=0x9b59b6
            )
            await i.edit_original_response(embed=embed, view=CustomizationHubView(self.author_id))
        else:
            embed = await build_main_embed(i)
            await i.edit_original_response(embed=embed, view=MainMenuView(self.author_id))

