async def get_craft_pity(user_id: int, item_id: str) -> int:
    async with bot.db.execute(
        "SELECT failures FROM craft_pity WHERE user_id = ? AND item_id = ?",
        (user_id, item_id),
    ) as c:
        row = await c.fetchone()
    return (row[0] if row else 0) or 0


async def get_craft_chance(user_id: int, item_id: str, use_cat: bool) -> tuple[float, int, bool]:
    settings = CRAFT_SETTINGS.get(item_id, {"chance": 1.0, "gems": 0})
    base_chance = settings["chance"]
    pet_chance = await get_pet_bonus(user_id, "craft_chance")
    title_chance = await get_title_bonus(user_id, "craft_chance")
    pity = await get_craft_pity(user_id, item_id)
    pity_bonus = min(CRAFT_PITY_MAX, pity * CRAFT_PITY_BONUS)
    final_chance = min(
        1.0,
        base_chance
        + (CATALYST_BONUS if use_cat else 0)
        + pet_chance
        + title_chance
        + pity_bonus,
    )
    guaranteed = pity >= CRAFT_HARD_PITY - 1
    if guaranteed:
        final_chance = 1.0
    return final_chance, pity, guaranteed


async def open_craft_view(interaction: discord.Interaction, author_id: int, page: int = 0):
    user_id = interaction.user.id
    guild_id = interaction.guild_id
    custom = (await get_settings(guild_id))["custom_emojis"]
    chain_items = list(CRAFT_CHAIN.items())

    options_all = []  # <--- ВОТ ЭТА СТРОКА БЫЛА ПОТЕРЯНА
    
    for item_id, next_id in chain_items:
        async with bot.db.execute("SELECT name, emoji FROM items WHERE id = ?", (item_id,)) as c:
            src = await c.fetchone()
        async with bot.db.execute("SELECT name, emoji FROM items WHERE id = ?", (next_id,)) as c:
            dst = await c.fetchone()
        if not src or not dst:
            continue
        async with bot.db.execute(
            "SELECT COUNT(*) FROM inventory WHERE user_id = ? AND item_id = ? "
            "AND stars = 0 AND location IN ('profile', 'storage') "
            "AND COALESCE(is_locked, 0) = 0",
            (user_id, item_id)
        ) as c:
            count = (await c.fetchone())[0]
        
        emoji_str = custom.get(item_id, src[1])
        emoji_obj = parse_emoji_safe(emoji_str)  # Используем безопасную функцию
        
        craft_cost = craft_cost_for_item(item_id)
        options_all.append(discord.SelectOption(
            label=f"{src[0]} ({count}/{craft_cost}) → {dst[0]}",
            value=item_id,
            emoji=emoji_obj
        ))

    if not options_all:
        await interaction.followup.send("❌ Нет предметов для синтеза.", ephemeral=True)
        return

    total_pages = max(1, (len(options_all) + SHOP_SELECT_PAGE_SIZE - 1) // SHOP_SELECT_PAGE_SIZE)
    page = max(0, min(page, total_pages - 1))
    chunk = options_all[page * SHOP_SELECT_PAGE_SIZE: page * SHOP_SELECT_PAGE_SIZE + SHOP_SELECT_PAGE_SIZE]

    embed = BotEmbed(
        title="⚗️ Синтез",
        description=(
            f"Страница {page + 1}/{total_pages}\n"
            "Копии берутся из энергостанции и хранилища.\n"
            "Выбери предмет для синтеза:"
        ),
        color=0x3498db
    )
    await interaction.edit_original_response(
        embed=embed,
        view=CraftSelectView(author_id, chunk, page, total_pages)
    )


class CraftSelectView(SafeView):
    feature_key = "craft"
    def __init__(self, author_id: int, options: list[discord.SelectOption], page: int = 0, total_pages: int = 1):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.page = page
        self.total_pages = total_pages
        self.add_item(make_select("Выбери предмет для синтеза", options, self.item_select, row=0))

        if total_pages > 1:
            prev = discord.ui.Button(label="Стр.", emoji=get_emoji("_back"), style=discord.ButtonStyle.secondary, row=1)
            prev.callback = self.prev_page
            self.add_item(prev)
            nxt = discord.ui.Button(label="Стр.", emoji=get_emoji("_forward"), style=discord.ButtonStyle.secondary, row=1)
            nxt.callback = self.next_page
            self.add_item(nxt)

        mass = discord.ui.Button(
            label="Массовый синтез",
            emoji=get_emoji("_synthesis"),
            style=discord.ButtonStyle.success,
            row=1,
        )
        mass.callback = self.mass_craft
        self.add_item(mass)

        back = discord.ui.Button(label="Назад", emoji=get_emoji("_back"), style=discord.ButtonStyle.success, row=2)
        back.callback = self.back
        self.add_item(back)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("❌ Не твоё меню.", ephemeral=True)
            return False
        return True

    async def item_select(self, interaction: discord.Interaction):
        item_id = interaction.data["values"][0]
        await interaction.response.defer()
        settings = CRAFT_SETTINGS.get(item_id, {"chance": 1.0, "gems": 0})
        async with bot.db.execute("SELECT name, emoji FROM items WHERE id = ?", (item_id,)) as c:
            src = await c.fetchone()
        async with bot.db.execute("SELECT catalysts FROM players WHERE user_id = ?", (interaction.user.id,)) as c:
            cats = (await c.fetchone())[0]

        final_chance, pity, guaranteed = await get_craft_chance(
            interaction.user.id, item_id, False
        )
        chance_str = "100% (гарантия)" if guaranteed else f"{int(final_chance * 100)}%"
        pity_str = (
            f"\nPity: **{pity}/{CRAFT_HARD_PITY - 1}** "
            f"(+{int(min(CRAFT_PITY_MAX, pity * CRAFT_PITY_BONUS) * 100)}%)"
            if pity
            else ""
        )

        embed = BotEmbed(
            title="⚗️ Синтез",
            description=(
                f"Предмет: {src[1]} **{src[0]}**\n"
                f"Шанс успеха: **{chance_str}**{pity_str}\n"
                f"Стоимость: 💎 {settings['gems']}\n\n"
                f"Использовать катализатор (+{int(CATALYST_BONUS * 100)}%)?\n"
                f"У тебя катализаторов: **{cats}**"
            ),
            color=0x3498db
        )
        await interaction.edit_original_response(embed=embed, view=CraftConfirmView(self.author_id, item_id))

    async def mass_craft(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await show_mass_craft_confirm(interaction, self.author_id, self.page)

    async def prev_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await open_craft_view(interaction, self.author_id, self.page - 1)

    async def next_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await open_craft_view(interaction, self.author_id, self.page + 1)

    async def back(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await go_back(interaction, self.author_id, fallback="profile")


async def craft_attempt(
    user_id: int,
    item_id: str,
    use_cat: bool,
    use_starred: bool = False,
) -> dict:
    """Одна попытка синтеза. Возвращает результат и данные для embed."""
    next_id = CRAFT_CHAIN.get(item_id)
    if not next_id:
        return {"ok": False, "message": "Этот генератор нельзя синтезировать."}
    settings = CRAFT_SETTINGS.get(item_id, {"chance": 1.0, "gems": 0})
    base_chance, gem_cost = settings["chance"], settings["gems"]

    async with bot.db.execute(
        "SELECT name, emoji FROM items WHERE id = ?", (item_id,)
    ) as c:
        src = await c.fetchone()
    async with bot.db.execute(
        "SELECT name, emoji FROM items WHERE id = ?", (next_id,)
    ) as c:
        dst = await c.fetchone()
    if not src or not dst:
        return {"ok": False, "message": "Генератор не найден в базе."}
    src_name, src_emoji = src
    dst_name, dst_emoji = dst
    craft_cost = craft_cost_for_item(item_id)

    try:
        async with db_transaction():
            async with bot.db.execute(
                "SELECT location, slot, stars FROM inventory "
                "WHERE user_id = ? AND item_id = ? "
                "AND location IN ('profile', 'storage') "
                "ORDER BY stars ASC, "
                "CASE location WHEN 'profile' THEN 0 ELSE 1 END, "
                "slot ASC",
                (user_id, item_id),
            ) as c:
                all_copies = await c.fetchall()

            source_star = 0
            if use_starred:
                by_star: dict[int, list] = {}
                for row in all_copies:
                    by_star.setdefault(row[2], []).append(row)
                for star in sorted(by_star):
                    if len(by_star[star]) >= craft_cost:
                        owned = by_star[star][:craft_cost]
                        source_star = star
                        break
                else:
                    owned = []
            else:
                owned = [
                    row for row in all_copies if row[2] == 0
                ][:craft_cost]

            if len(owned) < craft_cost:
                suffix = (
                    "одинаковой звёздности"
                    if use_starred
                    else "без звёзд"
                )
                raise ValueError(
                    f"Нужно {craft_cost} × {src_name} {suffix}, "
                    f"у тебя {len(owned)}."
                )

            async with bot.db.execute(
                "SELECT gems, catalysts FROM players WHERE user_id = ?",
                (user_id,),
            ) as c:
                gems, cats = await c.fetchone()
            if gems < gem_cost:
                raise ValueError(f"Нужно 💎 {gem_cost}, у тебя {gems}.")
            if use_cat and cats < 1:
                raise ValueError("Нет катализаторов.")

            for location, slot, _star in owned:
                await bot.db.execute(
                    "DELETE FROM inventory "
                    "WHERE user_id = ? AND location = ? AND slot = ?",
                    (user_id, location, slot),
                )

            if gem_cost > 0:
                cur = await bot.db.execute(
                    "UPDATE players SET gems = gems - ? "
                    "WHERE user_id = ? AND gems >= ?",
                    (gem_cost, user_id, gem_cost),
                )
                if cur.rowcount == 0:
                    raise ValueError("Не хватает гемов.")

            catalyst_used = 0
            if use_cat:
                cur = await bot.db.execute(
                    "UPDATE players SET catalysts = catalysts - 1 "
                    "WHERE user_id = ? AND catalysts >= 1",
                    (user_id,),
                )
                if cur.rowcount == 0:
                    raise ValueError("Нет катализаторов.")
                catalyst_used = 1

            final_chance, pity, guaranteed = await get_craft_chance(
                user_id, item_id, use_cat
            )
            success = guaranteed or random.random() < final_chance

            await bot.db.execute(
                "INSERT INTO craft_log "
                "(user_id, item_id, success, gems_spent, catalyst_used) "
                "VALUES (?, ?, ?, ?, ?)",
                (user_id, item_id, int(success), gem_cost, catalyst_used),
            )

            if success:
                try:
                    await place_items(
                        user_id, next_id, 1, commit=False,
                        stars=CRAFT_RESULT_STARS,
                    )
                except ValueError:
                    loc, slot, _star = owned[0]
                    await bot.db.execute(
                        "INSERT INTO inventory "
                        "(user_id, slot, item_id, location, stars) "
                        "VALUES (?, ?, ?, ?, ?)",
                        (user_id, slot, next_id, loc, CRAFT_RESULT_STARS),
                    )
            else:
                try:
                    await place_items(
                        user_id, item_id, 1, commit=False,
                        stars=source_star,
                    )
                except ValueError:
                    log.exception(
                        "Не удалось вернуть копию после провала синтеза %s",
                        user_id,
                    )

            await bot.db.execute(
                "UPDATE players SET total_crafts = total_crafts + 1, "
                "total_successes = total_successes + ? WHERE user_id = ?",
                (int(success), user_id),
            )
            if success:
                await bot.db.execute(
                    "DELETE FROM craft_pity WHERE user_id = ? AND item_id = ?",
                    (user_id, item_id),
                )
            else:
                await bot.db.execute(
                    """
                    INSERT INTO craft_pity (user_id, item_id, failures)
                    VALUES (?, ?, 1)
                    ON CONFLICT(user_id, item_id)
                    DO UPDATE SET failures = failures + 1
                    """,
                    (user_id, item_id),
                )
    except ValueError as e:
        return {"ok": False, "message": str(e)}

    return {
        "ok": True,
        "success": success,
        "gem_cost": gem_cost,
        "craft_cost": craft_cost,
        "catalyst_used": catalyst_used,
        "base_chance": base_chance,
        "final_chance": final_chance,
        "pity": pity,
        "guaranteed": guaranteed,
        "src_name": src_name,
        "src_emoji": src_emoji,
        "dst_id": next_id,
        "dst_name": dst_name,
        "dst_emoji": dst_emoji,
        "result_stars": CRAFT_RESULT_STARS,
        "source_stars": source_star,
    }


class CraftConfirmView(SafeView):
    feature_key = "craft"
    def __init__(self, author_id: int, item_id: str, use_starred: bool = False):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.item_id = item_id
        self.use_starred = use_starred

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("❌ Не твоё меню.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Без катализатора", emoji=get_emoji("_synthesis"), style=discord.ButtonStyle.primary, row=0)
    async def no_catalyst(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        await self.do_craft(interaction, False)

    @discord.ui.button(label="С катализатором", emoji=get_emoji("_catalyst"), style=discord.ButtonStyle.success, row=0)
    async def with_catalyst(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        await self.do_craft(interaction, True)

    @discord.ui.button(label="Звёздные: выкл", emoji=get_emoji("_stars"), style=discord.ButtonStyle.secondary, row=1)
    async def toggle_starred(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.use_starred = not self.use_starred
        self.toggle_starred.label = (
            "Звёздные: вкл" if self.use_starred else "Звёздные: выкл"
        )
        self.toggle_starred.style = (
            discord.ButtonStyle.success
            if self.use_starred
            else discord.ButtonStyle.secondary
        )
        await interaction.response.defer()
        await interaction.edit_original_response(view=self)
        if self.use_starred:
            await interaction.followup.send(
                "⚠️ Будут использованы звёздные копии, результат синтеза будет 0★.",
                ephemeral=True,
            )

    @discord.ui.button(label="Отмена", emoji=get_emoji("_cancel"), style=discord.ButtonStyle.secondary, row=1)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        embed = await build_profile_embed(interaction)
        await interaction.edit_original_response(embed=embed, view=ProfileView(self.author_id))

    async def do_craft(self, interaction: discord.Interaction, use_cat: bool):
        result = await craft_attempt(
            self.author_id, self.item_id, use_cat, use_starred=self.use_starred
        )
        if not result["ok"]:
            return await self.fail(interaction, f"❌ {result['message']}")

        user_id = self.author_id
        success = result["success"]
        use_cat = bool(result["catalyst_used"])
        base_chance = result["base_chance"]
        final_chance = result["final_chance"]
        pity = result["pity"]
        guaranteed = result["guaranteed"]
        gem_cost = result["gem_cost"]
        craft_cost = result["craft_cost"]
        src_name = result["src_name"]
        src_emoji = result["src_emoji"]
        dst_name = result["dst_name"]
        dst_emoji = result["dst_emoji"]
        result_stars = result["result_stars"]

        await sort_inventory(user_id, "profile")
        await sort_inventory(user_id, "storage")

        await update_story_quests(user_id, "synthesize", 1)
        await update_quest_progress(user_id, "craft_1")
        await update_quest_progress(user_id, "craft_3")
        await update_quest_progress(user_id, "craft_5")
        if success:
            await update_quest_progress(user_id, "success_2")
        if use_cat:
            await update_quest_progress(user_id, "use_catalyst")

        clan = await get_clan(user_id)
        if clan:
            await update_clan_quest(clan[0], "synthesize", 1)

        unlocked = await check_achievements(user_id)
        await add_season_xp(
            user_id,
            season_xp_amount(
                "craft_success" if success else "craft_fail"
            ),
            interaction.guild_id,
            action="craft_success" if success else "craft_fail",
        )
        onboarding = await complete_onboarding_step(user_id, "craft")

        if guaranteed:
            chance_str = "🎲 100% (гарантия pity)"
        else:
            chance_str = f"🎲 {int(final_chance * 100)}%"
            if pity:
                chance_str += f" (pity {pity}/{CRAFT_HARD_PITY - 1})"
            if use_cat:
                chance_str += f" (база {int(base_chance * 100)}% + 🧪)"
        gem_str = f" | 💎 {gem_cost}" if gem_cost else ""
        if success:
            msg = (
                f"⚗️ Успех! {craft_cost}×{src_emoji} {src_name} → "
                f"1×{dst_emoji} {dst_name} "
                f"{result_stars}★\n{chance_str}{gem_str}"
            )
        else:
            msg = (
                f"💥 Провал! Сгорело {craft_cost - 1}×{src_emoji} "
                f"{src_name}, 1 копия возвращена.\n{chance_str}{gem_str}"
            )
        if unlocked:
            msg += "\n🏆 " + ", ".join(f"{e} {n}" for e, n, _ in unlocked)
        if onboarding:
            msg += (
                f"\n🚀 Первый шаг: **{ONBOARDING_STEPS['craft'][0]}** "
                f"+🪙 {onboarding['coins']} +💎 {onboarding['gems']}."
            )

        embed = BotEmbed(title="⚗️ Результат синтеза", description=msg, color=0x9b59b6)
        await interaction.edit_original_response(embed=embed, view=ProfileView(self.author_id))

    async def fail(self, interaction: discord.Interaction, msg: str):
        embed = BotEmbed(title="❌ Ошибка", description=msg, color=0xe74c3c)
        await interaction.edit_original_response(embed=embed, view=ProfileView(self.author_id))


async def mass_craft_all(
    user_id: int,
    guild_id: int | None,
    use_cat: bool = False,
    use_starred: bool = False,
    max_result_id: str | None = None,
) -> dict:
    """Выполняет все доступные синтезы и возвращает статистику попыток."""
    successes = failures = attempts = 0
    gems_spent = catalysts_used = 0
    crafted: dict[tuple[str, int], dict] = {}

    chain = list(CRAFT_CHAIN)
    if max_result_id in chain:
        allowed = chain[: chain.index(max_result_id)]
    else:
        allowed = chain

    while True:
        progressed = False
        for item_id in allowed:
            result = await craft_attempt(
                user_id, item_id, use_cat, use_starred=use_starred
            )
            if not result["ok"]:
                continue
            progressed = True
            attempts += 1
            gems_spent += result["gem_cost"]
            catalysts_used += result["catalyst_used"]
            if result["success"]:
                successes += 1
                key = (result["dst_id"], result["result_stars"])
                entry = crafted.setdefault(
                    key,
                    {
                        "item_id": result["dst_id"],
                        "name": result["dst_name"],
                        "emoji": result["dst_emoji"],
                        "stars": result["result_stars"],
                        "count": 0,
                    },
                )
                entry["count"] += 1
            else:
                failures += 1
        if not progressed:
            break

    unlocked = []
    if attempts:
        await sort_inventory(user_id, "profile")
        await sort_inventory(user_id, "storage")
        await update_story_quests(user_id, "synthesize", attempts)
        await update_quest_progress(user_id, "craft_1", attempts)
        await update_quest_progress(user_id, "craft_3", attempts)
        await update_quest_progress(user_id, "craft_5", attempts)
        if successes:
            await update_quest_progress(user_id, "success_2", successes)
        if catalysts_used:
            await update_quest_progress(
                user_id, "use_catalyst", catalysts_used
            )
        clan = await get_clan(user_id)
        if clan:
            await update_clan_quest(clan[0], "synthesize", attempts)
        unlocked = await check_achievements(user_id)
        if successes:
            await add_season_xp(
                user_id,
                season_xp_amount("craft_success", successes),
                guild_id,
                action="craft_success",
            )
        if failures:
            await add_season_xp(
                user_id,
                season_xp_amount("craft_fail", failures),
                guild_id,
                action="craft_fail",
            )
        await complete_onboarding_step(user_id, "craft")

    return {
        "attempts": attempts,
        "successes": successes,
        "failures": failures,
        "gems_spent": gems_spent,
        "catalysts_used": catalysts_used,
        "unlocked": unlocked,
        "crafted": list(crafted.values()),
    }


async def _mass_craft_target_options():
    target_ids = list(dict.fromkeys(CRAFT_CHAIN.values()))[:24]
    async with bot.db.execute(
        "SELECT id, name, emoji FROM items"
    ) as c:
        info = {row[0]: (row[1], row[2]) for row in await c.fetchall()}
    options = [
        discord.SelectOption(
            label="Все генераторы",
            value="__all__",
            description="Синтезировать до максимально возможного тира",
            emoji=parse_emoji_safe(get_emoji("_generators")),
        )
    ]
    for item_id in target_ids:
        name, emoji = info.get(item_id, (item_id, ""))
        options.append(
            discord.SelectOption(
                label=f"До {name}"[:100],
                value=item_id,
                emoji=parse_emoji_safe(
                    emoji or get_emoji("_generators")
                ),
            )
        )
    return options


async def show_mass_craft_confirm(
    interaction: discord.Interaction, author_id: int, page: int = 0
):
    user_id = interaction.user.id
    async with bot.db.execute(
        "SELECT gems, catalysts FROM players WHERE user_id = ?", (user_id,)
    ) as c:
        row = await c.fetchone()
    gems, catalysts = row if row else (0, 0)

    possible = 0
    for item_id in CRAFT_CHAIN:
        async with bot.db.execute(
            "SELECT COUNT(*) FROM inventory "
            "WHERE user_id = ? AND item_id = ? AND stars = 0 "
            "AND location IN ('profile', 'storage')",
            (user_id, item_id),
        ) as c:
            count = (await c.fetchone())[0]
        possible += count // craft_cost_for_item(item_id)

    async with bot.db.execute(
        "SELECT item_id, stars, COUNT(*) FROM inventory "
        "WHERE user_id = ? AND location IN ('profile', 'storage') "
        "AND stars > 0 GROUP BY item_id, stars",
        (user_id,),
    ) as c:
        star_rows = await c.fetchall()
    starred_count = sum(row[2] for row in star_rows)
    starred_possible = any(
        count >= craft_cost_for_item(item_id)
        for item_id, _stars, count in star_rows
    )

    if possible <= 0 and not starred_possible:
        await interaction.followup.send(
            "❌ Нет копий для массового синтеза.", ephemeral=True
        )
        return

    target_options = await _mass_craft_target_options()
    starred_line = ""
    if starred_count and starred_possible:
        starred_line = (
            f"\n⚠️ Звёздных копий: **{starred_count}**. "
            "По умолчанию они не используются; включи «Звёздные», "
            "чтобы синтезировать и их (результат будет 0★)."
        )
    embed = BotEmbed(
        title="⚗️ Массовый синтез",
        description=(
            f"0★-синтезов (минимум): **{possible}**\n"
            f"Копии берутся из энергостанции и хранилища.\n"
            f"Гемов: **💎 {gems}** · катализаторов: **{catalysts}**"
            f"{starred_line}\n\n"
            "Выбери, до какого генератора синтезировать, и запусти. "
            "После завершения бот покажет успешные/неудачные попытки "
            "и список созданных генераторов."
        ),
        color=0x3498db,
    )
    await interaction.edit_original_response(
        embed=embed,
        view=MassCraftConfirmView(
            author_id,
            page,
            catalysts,
            target_options=target_options,
            starred_count=starred_count,
        ),
    )


class MassCraftConfirmView(BaseView):
    feature_key = "craft"

    def __init__(
        self,
        author_id: int,
        page: int = 0,
        catalysts: int = 0,
        target_options: list | None = None,
        starred_count: int = 0,
    ):
        super().__init__(author_id, timeout=120)
        self.page = page
        self.catalysts = catalysts
        self.target_id = None
        self.use_starred = False
        self.starred_count = starred_count
        if catalysts < 1:
            self.with_catalyst.disabled = True
        if target_options:
            self.add_item(
                make_select(
                    "До какого генератора синтезировать",
                    target_options,
                    self.select_target,
                    row=0,
                )
            )
        self.starred_toggle.label = "Звёздные: выкл"
        self.starred_toggle.style = discord.ButtonStyle.secondary
        if starred_count < CRAFT_COST_EARLY:
            self.starred_toggle.disabled = True

    async def select_target(self, interaction: discord.Interaction):
        value = interaction.data["values"][0]
        self.target_id = None if value == "__all__" else value
        await interaction.response.defer()

    async def _run(self, interaction: discord.Interaction, use_cat: bool):
        result = await mass_craft_all(
            self.author_id,
            interaction.guild_id,
            use_cat,
            use_starred=self.use_starred,
            max_result_id=self.target_id,
        )
        if result["attempts"] == 0:
            description = (
                "❌ Не удалось выполнить ни одной попытки.\n"
                "Проверь копии генераторов, гемы и катализаторы."
            )
            color = 0xe74c3c
        else:
            description = (
                f"Успешно: **{result['successes']}**\n"
                f"Неудачно: **{result['failures']}**\n"
                f"Всего попыток: **{result['attempts']}**\n"
                f"Потрачено гемов: **💎 {result['gems_spent']}**"
            )
            if result["catalysts_used"]:
                description += (
                    f"\nИспользовано катализаторов: "
                    f"**{result['catalysts_used']}**"
                )
            if result["crafted"]:
                made = sorted(
                    result["crafted"],
                    key=lambda entry: (entry["stars"], entry["name"]),
                )
                description += "\n\nСделано:\n" + "\n".join(
                    f"• {entry['count']}× {entry['emoji']} "
                    f"{entry['name']} {entry['stars']}★"
                    for entry in made
                )
            if result["unlocked"]:
                description += "\n\n🏆 " + ", ".join(
                    f"{emoji} {name}"
                    for emoji, name, _ in result["unlocked"]
                )
            color = 0x2ecc71 if result["successes"] else 0xf1c40f
        embed = BotEmbed(
            title="⚗️ Массовый синтез завершён",
            description=description,
            color=color,
        )
        await interaction.edit_original_response(
            embed=embed, view=ProfileView(self.author_id)
        )

    @discord.ui.button(
        label="Без катализатора",
        emoji=get_emoji("_synthesis"),
        style=discord.ButtonStyle.primary,
        row=1,
    )
    async def no_catalyst(
        self, interaction: discord.Interaction, button: discord.ui.Button
    ):
        await interaction.response.defer()
        await self._run(interaction, False)

    @discord.ui.button(
        label="С катализатором",
        emoji=get_emoji("_catalyst"),
        style=discord.ButtonStyle.success,
        row=1,
    )
    async def with_catalyst(
        self, interaction: discord.Interaction, button: discord.ui.Button
    ):
        await interaction.response.defer()
        await self._run(interaction, True)

    @discord.ui.button(
        label="Звёздные: выкл",
        emoji=get_emoji("_stars"),
        style=discord.ButtonStyle.secondary,
        row=2,
    )
    async def starred_toggle(
        self, interaction: discord.Interaction, button: discord.ui.Button
    ):
        self.use_starred = not self.use_starred
        self.starred_toggle.label = (
            "Звёздные: вкл" if self.use_starred else "Звёздные: выкл"
        )
        self.starred_toggle.style = (
            discord.ButtonStyle.success
            if self.use_starred
            else discord.ButtonStyle.secondary
        )
        await interaction.response.defer()
        await interaction.edit_original_response(view=self)
        if self.use_starred:
            await interaction.followup.send(
                "⚠️ Будут использованы звёздные копии, результат синтеза будет 0★.",
                ephemeral=True,
            )

    @discord.ui.button(
        label="Отмена",
        emoji=get_emoji("_cancel"),
        style=discord.ButtonStyle.secondary,
        row=2,
    )
    async def cancel(
        self, interaction: discord.Interaction, button: discord.ui.Button
    ):
        await interaction.response.defer()
        await open_craft_view(interaction, self.author_id, self.page)


