async def open_auction_sell_select(
    interaction: discord.Interaction,
    author_id: int,
    page: int = 0,
):
    hidden = tuple(sorted(GEN_SYNTHESIS_ONLY))
    hidden_ph = ",".join("?" for _ in hidden)
    async with bot.db.execute(f"""
        SELECT inv.slot, inv.item_id, inv.stars, i.name, i.emoji
        FROM inventory inv
        JOIN items i ON inv.item_id = i.id
        WHERE inv.user_id = ? AND inv.location = 'profile'
              AND COALESCE(inv.is_locked, 0) = 0
              AND inv.item_id NOT IN ({hidden_ph})
              AND (i.buyable = 0 OR inv.stars > 0)
        ORDER BY inv.slot ASC
    """, (author_id, *hidden)) as c:
        rows = await c.fetchall()

    if not rows:
        return await interaction.followup.send(
            "❌ На энергостанции нет предметов для аукциона "
            "(магазинные 0★ продаются в магазине).",
            ephemeral=True,
        )

    page_size = 10
    total_pages = max(1, (len(rows) + page_size - 1) // page_size)
    page = max(0, min(page, total_pages - 1))
    chunk = rows[page * page_size:page * page_size + page_size]

    options = []
    for slot, item_id, stars, name, default_emoji in chunk:
        options.append(discord.SelectOption(
            label=f"Слот {slot}: {name} ({stars}★)"[:100],
            value=f"{slot}:{item_id}:{stars}",
            emoji=parse_emoji_safe(default_emoji),
        ))

    embed = BotEmbed(
        title="🏛️ Выставить лот",
        description=f"Страница {page + 1}/{total_pages}\nВыбери предмет из энергостанции.",
        color=0xf1c40f,
    )
    await interaction.edit_original_response(
        embed=embed,
        view=AuctionSellSelectView(author_id, options, page, total_pages),
    )


