class QuestsView(BaseView):
    feature_key = "quests"
    home_row = 2
    def __init__(self, author_id: int, return_to: str = "main", timeout: int = 600):
        super().__init__(author_id, timeout)
        self.return_to = return_to
        if return_to == "main":
            self.remove_item(self.back)

    @discord.ui.button(label="Забрать награду", emoji=get_emoji("_approve"), style=discord.ButtonStyle.success, row=1)
    async def claim_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        user_id = interaction.user.id
        quests, progress, claimed = await get_or_create_daily_quests(user_id)
        options = []
        for qid in quests:
            if qid in claimed:
                continue
            desc, target, reward_gems, reward_coins = QUEST_POOL[qid]
            done = progress[qid] >= target
            label = f"{desc} — {progress[qid]}/{target}" + (" 🎁" if done else "")
            options.append(discord.SelectOption(label=label[:100], value=qid, emoji=get_emoji("_dailyquests") if done else "⏳"))
        if not options:
            await interaction.followup.send("❌ Нет доступных заданий.", ephemeral=True)
            return
        embed = BotEmbed(title="🎁 Забрать награду", description="Выбери задание:", color=0x3498db)
        await interaction.edit_original_response(
            embed=embed,
            view=ClaimQuestSelectView(self.author_id, options, self.return_to),
        )

    @discord.ui.button(label="Назад", emoji=get_emoji("_back"), style=discord.ButtonStyle.success, row=1)
    async def back(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        if self.return_to == "quests":
            embed = BotEmbed(
                title=f"{get_emoji('_quests')} Квесты",
                description="Выбери раздел: сюжетные квесты или ежедневные задания.",
                color=0x3498db
            )
            await interaction.edit_original_response(embed=embed, view=QuestsHubView(self.author_id))
        else:
            await self.back_to_home(interaction)


class ClaimQuestSelectView(SafeView):
    feature_key = "quests"
    def __init__(
        self,
        author_id: int,
        options: list[discord.SelectOption],
        return_to: str = "main",
    ):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.return_to = return_to
        self.add_item(make_select("Выбери задание", options, self.quest_select, row=0))
        back = discord.ui.Button(label="Назад", emoji=get_emoji("_back"), style=discord.ButtonStyle.success, row=1)
        back.callback = self.back
        self.add_item(back)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("❌ Не твоё меню.", ephemeral=True)
            return False
        return True

    async def quest_select(self, interaction: discord.Interaction):
        qid = interaction.data["values"][0]
        await interaction.response.defer()
        user_id = interaction.user.id
        quests, progress, claimed = await get_or_create_daily_quests(user_id)
        if qid not in quests or qid in claimed:
            await self.fail(interaction, "❌ Недоступно.")
            return
        desc, target, reward_gems, reward_coins = QUEST_POOL[qid]
        if progress[qid] < target:
            await self.fail(interaction, f"❌ Не выполнено: {progress[qid]}/{target}.")
            return
        prestige = await get_prestige_points(user_id)
        scale = reward_scale(prestige)
        reward_gems = max(1, int(reward_gems * scale))
        reward_coins = max(1, int(reward_coins * scale))
        claimed.append(qid)
        await bot.db.execute(
            "UPDATE players SET daily_quest_claimed = ?, gems = gems + ?, coins = coins + ?, "
            "total_gems_earned = total_gems_earned + ?, "
            "total_coins_earned = total_coins_earned + ?, "
            "lifetime_production = lifetime_production + ? WHERE user_id = ?",
            (json.dumps(claimed), reward_gems, reward_coins,
             reward_gems, reward_coins, reward_coins, user_id)
        )
        await commit_if_needed()
        await add_season_xp(
            user_id, season_xp_amount("quest"), interaction.guild_id, action="quest"
        )
        embed = BotEmbed(
            title="🎁 Награда получена",
            description=f"💎 **{reward_gems}** гемов и 🪙 **{reward_coins}** монет за «{desc}»!",
            color=0x2ecc71,
        )
        await interaction.edit_original_response(
            embed=embed, view=QuestsView(self.author_id, self.return_to)
        )

    async def fail(self, interaction: discord.Interaction, msg: str):
        embed = BotEmbed(title="❌ Ошибка", description=msg, color=0xe74c3c)
        await interaction.edit_original_response(
            embed=embed, view=QuestsView(self.author_id, self.return_to)
        )

    async def back(self, interaction: discord.Interaction):
        await interaction.response.defer()
        embed = await build_quests_embed(interaction)
        await interaction.edit_original_response(
            embed=embed, view=QuestsView(self.author_id, self.return_to)
        )


