class BuyItemQuantityView(SafeView):
    feature_key = "shop"
    home_row = 2
    def __init__(self, author_id: int, item_id: str, page: int = 0):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.item_id = item_id
        self.page = page
        
        options = [
            discord.SelectOption(
                label=f"{q} шт",
                value=str(q),
                emoji=parse_emoji_safe(get_emoji("_buy")),
            )
            for q in (1, 5, 10, 25, 50)
        ]
        self.add_item(make_select("Сколько купить?", options, self.quantity_select, row=0))
        
        back = discord.ui.Button(
            label="Назад", 
            emoji=BOT_BTN_EMOJIS.get("_back", "◀️"), 
            style=discord.ButtonStyle.success,
            row=1
        )
        back.callback = self.back
        self.add_item(back)

        custom = discord.ui.Button(
            label="Своё количество",
            emoji=get_emoji("_settings"),
            style=discord.ButtonStyle.primary,
            row=1,
        )
        custom.callback = self.custom_quantity
        self.add_item(custom)

    async def custom_quantity(self, interaction: discord.Interaction):
        await interaction.response.send_modal(
            CustomBuyQuantityModal(
                self.author_id, self.item_id, self.page
            )
        )

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await self.check_owner(interaction)

    async def quantity_select(
        self, interaction: discord.Interaction, qty: int | None = None
    ):
        if not interaction.response.is_done():
            await interaction.response.defer()
        if qty is None:
            qty = int(interaction.data["values"][0])
        user_id = interaction.user.id

        async with bot.db.execute("SELECT price, name, buyable, emoji FROM items WHERE id = ?", (self.item_id,)) as c:
            item = await c.fetchone()
            
        if not item:
            return await self.fail(interaction, "❌ Предмет не найден.")
            
        price, name, buyable, default_emoji = item
        
        if not buyable:
            return await self.fail(interaction, f"❌ **{name}** нельзя купить.")

        starter = await is_starter_shop_purchase(user_id, self.item_id)
        discount = 0
        if starter and qty > 0:
            total_cost = starter_shop_total(price, qty)
            discount = max(0, price * qty - total_cost)
        else:
            total_cost = price * qty

        # Проверка баланса
        async with bot.db.execute("SELECT coins FROM players WHERE user_id = ?", (user_id,)) as c:
            balance = (await c.fetchone())[0]
            
        if balance < total_cost:
            coin = str(BOT_BTN_EMOJIS.get("_coin", "🪙"))
            return await self.fail(interaction, f"❌ Нужно {total_cost} {coin}, у тебя {balance}.")

        coin = str(BOT_BTN_EMOJIS.get("_coin", "🪙"))
        # Списание и выдача должны быть одной транзакцией: иначе при
        # нехватке места монеты списываются без предмета.
        try:
            async with db_transaction():
                cursor = await bot.db.execute(
                    "UPDATE players SET coins = coins - ? "
                    "WHERE user_id = ? AND coins >= ?",
                    (total_cost, user_id, total_cost),
                )
                if cursor.rowcount == 0:
                    raise ValueError(
                        f"Не хватает монет (нужно {total_cost} {coin})."
                    )
                to_profile, to_storage, to_temp = await place_items(
                    user_id, self.item_id, qty, commit=False
                )
        except ValueError as e:
            return await self.fail(interaction, f"❌ {e}")

        await sort_inventory(user_id, "profile")
        await sort_inventory(user_id, "storage")

        await update_quest_progress(user_id, "buy_3", qty)
        await update_quest_progress(user_id, "buy_10", qty)
        await update_quest_progress(user_id, "buy_25", qty)
        unlocked = await check_achievements(user_id)
        onboarding = None
        if self.item_id.endswith("_gen"):
            onboarding = await complete_onboarding_step(user_id, "buy_generator")

        coin = str(BOT_BTN_EMOJIS.get("_coin", "🪙"))
        emoji = default_emoji or "⚙️" 
        
        msg = (
            f"✅ Куплено {emoji} **{name}** — {qty} "
            f"{plural_ru(qty, 'штука', 'штуки', 'штук')} "
            f"за {coin} {format_price(total_cost)}."
        )
        if discount:
            msg += (
                f"\n🎁 Стартовая скидка на первый генератор: "
                f"−{coin} {format_price(discount)}."
            )
        if to_storage > 0 or to_temp > 0:
            msg += (
                f"\n📦 {to_profile} на энергостанцию, {to_storage} в хранилище, "
                f"{to_temp} во временное хранилище."
            )
        if onboarding:
            msg += (
                f"\n🚀 Первый шаг: **{ONBOARDING_STEPS['buy_generator'][0]}** "
                f"+🪙 {onboarding['coins']}."
            )
        if unlocked:
            msg += "\n🏆 " + ", ".join(f"{e} {n}" for e, n, _ in unlocked)
            
        embed = BotEmbed(title="🛒 Покупка", description=msg, color=0x2ecc71)
        embed = await fix_embed_emojis(embed)
        await interaction.edit_original_response(embed=embed, view=ShopView(self.author_id, self.page))
        
        # Клановый квест
        clan = await get_clan(user_id)
        if clan:
            await update_clan_quest(clan[0], "buy", qty)

        await update_story_quests(user_id, "buy", qty)

    async def fail(self, interaction: discord.Interaction, msg: str):
        embed = BotEmbed(title="❌ Ошибка", description=msg, color=0xe74c3c)
        await interaction.edit_original_response(embed=embed, view=ShopView(self.author_id, self.page))

    async def back(self, interaction: discord.Interaction):
        await interaction.response.defer()
        async with bot.db.execute(
            "SELECT id, name, price, emoji FROM items WHERE buyable = 1 ORDER BY price ASC"
        ) as c:
            rows = await c.fetchall()
        await open_shop_buy_select(interaction, self.author_id, rows, self.page)


