class CollectionView(BaseView):
    def __init__(self, author_id: int, page: int, total_pages: int):
        super().__init__(author_id)
        self.page = page
        self.total_pages = total_pages

        if total_pages > 1:
            prev = discord.ui.Button(label="Стр.", emoji=get_emoji("_back"), style=discord.ButtonStyle.secondary, row=0)
            prev.callback = self.prev_page
            self.add_item(prev)
            nxt = discord.ui.Button(label="Стр.", emoji=get_emoji("_forward"), style=discord.ButtonStyle.secondary, row=0)
            nxt.callback = self.next_page
            self.add_item(nxt)

        back = discord.ui.Button(label="Назад", emoji=get_emoji("_back"), style=discord.ButtonStyle.success, row=1)
        back.callback = self.back
        self.add_item(back)

    async def prev_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        page = max(0, self.page - 1)
        embed, total_pages = await build_collection_embed(interaction, page)
        await interaction.edit_original_response(
            embed=embed, view=CollectionView(self.author_id, page, total_pages)
        )

    async def next_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        page = min(self.total_pages - 1, self.page + 1)
        embed, total_pages = await build_collection_embed(interaction, page)
        await interaction.edit_original_response(
            embed=embed, view=CollectionView(self.author_id, page, total_pages)
        )

    async def back(self, interaction: discord.Interaction):
        await interaction.response.defer()
        embed = await build_user_profile_embed(interaction)
        await interaction.edit_original_response(
            embed=embed, view=UserProfileView(self.author_id)
        )


