class UserResetModal(discord.ui.Modal, title="Сброс прогресса"):
    confirm = discord.ui.TextInput(label="Введите СБРОСИТЬ", required=True)

    def __init__(self, author_id: int, main_message=None):
        super().__init__()
        self.author_id = author_id
        self.main_message = main_message

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        if self.confirm.value.strip().upper() != "СБРОСИТЬ":
            return await interaction.followup.send("❌ Отменено.", ephemeral=True)

        if await get_clan(self.author_id):
            return await interaction.followup.send(
                "❌ Сначала выйди из клана (или попроси администратора).",
                ephemeral=True,
            )

        settings = await get_settings(interaction.guild_id)
        start_coins = min(
            int(settings["start_coins"]), MAX_START_COINS
        )
        released_bids = 0

        try:
            async with db_transaction():
                # Не теряем эскроу/долги при сбросе: сначала закрываем обязательства.
                for label, sql in (
                    ("вклад", "SELECT 1 FROM bank_deposits WHERE user_id = ?"),
                    (
                        "кредит",
                        "SELECT 1 FROM bank_loans WHERE user_id = ? "
                        "AND COALESCE(status, 'active') = 'active'",
                    ),
                    (
                        "ордера биржи",
                        "SELECT 1 FROM market_orders WHERE user_id = ? "
                        "AND status = 'active'",
                    ),
                    (
                        "аукционы",
                        "SELECT 1 FROM auctions WHERE seller_id = ? "
                        "AND status = 'active'",
                    ),
                    (
                        "почту",
                        "SELECT 1 FROM mailbox WHERE user_id = ?",
                    ),
                ):
                    async with bot.db.execute(sql, (self.author_id,)) as c:
                        if await c.fetchone():
                            raise ValueError(
                                f"Сначала закрой {label}: сброс не должен "
                                "терять активные обязательства."
                            )

                # Убираем игрока из отряда и удаляем его приглашения.
                await detach_user_from_raid_party(self.author_id)

                # Снимаем ставки на чужих лотах до обнуления баланса.
                released_bids, _refunded = await release_active_auction_bids(
                    self.author_id
                )

                # Возвращаем ставки по активным лотам игрока и удаляем лоты.
                async with bot.db.execute(
                    "SELECT id, current_bidder, current_bid FROM auctions "
                    "WHERE seller_id = ? AND status = 'active'",
                    (self.author_id,),
                ) as c:
                    lots = await c.fetchall()
                for aid, bidder, bid in lots:
                    if bidder and bid:
                        await bot.db.execute(
                            "UPDATE players SET coins = coins + ? WHERE user_id = ?",
                            (bid, bidder),
                        )
                    await bot.db.execute(
                        "DELETE FROM auction_bids WHERE auction_id = ?", (aid,)
                    )
                    await bot.db.execute("DELETE FROM auctions WHERE id = ?", (aid,))

                await bot.db.execute("""
                    UPDATE players SET
                        coins = ?, gems = 0, catalysts = 0,
                        grid_size = 9, storage_size = 36, income_bonus = 0.0,
                        total_crafts = 0, total_successes = 0,
                        total_coins_earned = 0, total_gems_earned = 0,
                        lifetime_production = 0,
                        last_collected = CURRENT_TIMESTAMP,
                        last_gem_collected = CURRENT_TIMESTAMP,
                        daily_quest_date = NULL,
                        daily_quest_progress = '{}',
                        daily_quest_claimed = '[]',
                        streak_days = 0,
                        last_daily = NULL,
                        title = 'Новичок',
                        active_pet = NULL,
                        last_tax_time = CURRENT_TIMESTAMP,
                        raid_wins = 0,
                        prestige_points = 0,
                        exchange_day = NULL,
                        exchange_coins_today = 0,
                        exchange_gems_today = 0
                    WHERE user_id = ?
                """, (start_coins, self.author_id))

                for table in (
                    "inventory", "player_achievements", "player_upgrades",
                    "craft_log", "craft_pity", "star_pity",
                    "user_pets_v2", "autocollectors",
                    "advent_progress", "advent_state", "bank_deposits",
                    "bank_loans", "bank_history", "user_notifications", "player_quests",
                    "user_cosmetics", "tax_log", "raid_cooldowns",
                    "duel_cooldowns", "espionage_cooldowns", "season_progress",
                    "season_xp_log", "market_orders", "onboarding_progress",
                    "clan_applications", "giveaway_entries", "mailbox",
                    "notification_fallback", "player_collection",
                ):
                    await bot.db.execute(
                        f"DELETE FROM {table} WHERE user_id = ?", (self.author_id,)
                    )

                await bot.db.execute(
                    "DELETE FROM duel_history WHERE winner_id = ? OR loser_id = ?",
                    (self.author_id, self.author_id),
                )
                await bot.db.execute(
                    "DELETE FROM raid_loot_log WHERE user_id = ?", (self.author_id,)
                )
        except ValueError as exc:
            return await interaction.followup.send(f"❌ {exc}", ephemeral=True)
        except Exception:
            log.exception("Не удалось сбросить прогресс пользователя %s", self.author_id)
            return await interaction.followup.send(
                "❌ Не удалось сбросить прогресс. Попробуй позже.", ephemeral=True
            )

        onboarding_cache = getattr(bot, "_onboarding_complete_cache", None)
        if onboarding_cache is not None:
            onboarding_cache.discard(self.author_id)
        _top_cache.clear()

        await log_admin_action(self.author_id, self.author_id, "self_reset", "user reset")
        reset_message = (
            "✅ Прогресс сброшен. Энергостанция, инвентарь, питомцы и квесты очищены."
        )
        if released_bids:
            reset_message += (
                f"\n🏛️ Сняты активные ставки на аукционах: **{released_bids}**."
            )
        await interaction.followup.send(reset_message, ephemeral=True)
        if self.main_message:
            embed = await build_user_profile_embed(interaction)
            try:
                await self.main_message.edit(
                    embed=embed, view=UserProfileView(self.author_id)
                )
            except discord.HTTPException:
                pass


