async def open_admin_logs(interaction: discord.Interaction, author_id: int, page: int = 0):
    guild_id = interaction.guild_id
    rows, total, page, total_pages = await get_admin_logs_page(
        guild_id, page, PAGE_SIZE
    )

    embed = BotEmbed(
        title="📜 Логи администрации",
        description=(
            f"Страница {page + 1}/{total_pages} | Всего записей: {total}\n"
            f"Фильтр: {'этот сервер + глобальные' if guild_id else 'все серверы'}"
        ),
        color=0xe74c3c,
    )
    if not rows:
        embed.add_field(name="Пусто", value="Действий пока не было.")
    for admin_id, target_id, action, details, ts, log_guild_id in rows:
        guild_text = f" · сервер `{log_guild_id}`" if log_guild_id else " · глобально"
        embed.add_field(
            name=f"`{action}` — <@{admin_id}> → <@{target_id}>",
            value=f"{details}{guild_text}\n{ts}",
            inline=False,
        )
    await interaction.edit_original_response(
        embed=embed,
        view=AdminLogsView(author_id, page, total_pages),
    )


class AdminLogsView(AdminView):
    def __init__(self, author_id: int, page: int, total_pages: int):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.page = page
        self.total_pages = total_pages
        if total_pages > 1:
            prev = discord.ui.Button(label="Стр.", emoji=get_emoji("_back"), style=discord.ButtonStyle.secondary)
            prev.callback = self.prev_page
            self.add_item(prev)
            nxt = discord.ui.Button(label="Стр.", emoji=get_emoji("_forward"), style=discord.ButtonStyle.secondary)
            nxt.callback = self.next_page
            self.add_item(nxt)
        back = discord.ui.Button(label="Назад", emoji=get_emoji("_back"), style=discord.ButtonStyle.success)
        back.callback = self.back
        self.add_item(back)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await super().interaction_check(interaction)

    async def prev_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await open_admin_logs(interaction, self.author_id, self.page - 1)

    async def next_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await open_admin_logs(interaction, self.author_id, self.page + 1)

    async def back(self, interaction: discord.Interaction):
        await interaction.response.defer()
        embed = BotEmbed(title="🛡️ Панель администратора", color=0xe74c3c)
        await interaction.edit_original_response(embed=embed, view=AdminPanelView(self.author_id))

# ---------- АДМИН-МОДАЛКИ ----------

class AdminProfileModal(discord.ui.Modal, title="Профиль игрока"):
    user_id = discord.ui.TextInput(label="ID пользователя", placeholder="123456789", required=True)

    def __init__(self, author_id: int):
        super().__init__()
        self.author_id = author_id

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        try:
            uid = int(self.user_id.value)
        except ValueError:
            await interaction.followup.send("❌ ID должен быть числом.", ephemeral=True)
            return
        async with bot.db.execute("SELECT 1 FROM players WHERE user_id = ?", (uid,)) as c:
            if not await c.fetchone():
                await interaction.followup.send("❌ Игрок не найден.", ephemeral=True)
                return

        async with bot.db.execute("""
            SELECT coins, gems, catalysts, grid_size, income_bonus,
                   total_crafts, total_successes, last_collected, last_gem_collected
            FROM players WHERE user_id = ?
        """, (uid,)) as c:
            row = await c.fetchone()
        (coins, gems, catalysts, grid_size, _bonus, total_crafts, total_successes, last_coins, last_gems) = row
        bonus = await get_status_bonus(uid)

        async with bot.db.execute("""
            SELECT inv.location, inv.slot, i.name, i.emoji, inv.stars
            FROM inventory inv JOIN items i ON inv.item_id = i.id
            WHERE inv.user_id = ? ORDER BY inv.location, inv.slot
        """, (uid,)) as c:
            inv_rows = await c.fetchall()

        profile_items = [f"`{s}` {e} {n} ({st}⭐)" if st > 0 else f"`{s}` {e} {n}" for loc, s, n, e, st in inv_rows if loc == "profile"]
        storage_items = [f"`{s}` {e} {n} ({st}⭐)" if st > 0 else f"`{s}` {e} {n}" for loc, s, n, e, st in inv_rows if loc == "storage"]

        if len(profile_items) > 30:
            hidden = len(profile_items) - 30
            profile_items = profile_items[:30] + [f"…и ещё {hidden}"]
        if len(storage_items) > 30:
            hidden = len(storage_items) - 30
            storage_items = storage_items[:30] + [f"…и ещё {hidden}"]

        async with bot.db.execute("SELECT COUNT(*) FROM player_achievements WHERE user_id = ?", (uid,)) as c:
            ach_count = (await c.fetchone())[0]

        async with bot.db.execute("SELECT upgrade_id FROM player_upgrades WHERE user_id = ?", (uid,)) as c:
            upgrades = [r[0] for r in await c.fetchall()]

        def human_date(value):
            if not value:
                return "—"
            parsed = _parse_db_time(value)
            return (
                parsed.strftime("%d.%m.%Y %H:%M")
                if parsed
                else str(value)[:16]
            )

        embed = BotEmbed(title=f"🛡️ Профиль <@{uid}>", color=0xe74c3c)
        embed.add_field(name="ID", value=f"`{uid}`", inline=False)
        embed.add_field(name="Кошелёк", value=f"{COIN} {format_price(coins)} | {GEM} {format_price(gems)}", inline=True)
        embed.add_field(name="Катализаторы", value=f"🧪 {catalysts}", inline=True)
        embed.add_field(name="Сетка", value=f"{grid_size}", inline=True)
        embed.add_field(name="Бонус", value=f"+{int(bonus * 100)}%", inline=True)
        embed.add_field(name="Синтезы", value=f"{format_price(total_crafts)} (успешно: {format_price(total_successes)})", inline=True)
        embed.add_field(name="Достижения", value=f"{ach_count}", inline=True)
        embed.add_field(name="Апгрейды", value=", ".join(upgrades) if upgrades else "нет", inline=False)
        embed.add_field(name="Последний сбор монет", value=human_date(last_coins), inline=True)
        embed.add_field(name="Последний сбор гемов", value=human_date(last_gems), inline=True)
        embed.add_field(name=f"Энергостанция ({len(profile_items)})", value="\n".join(profile_items) if profile_items else "пусто", inline=False)
        embed.add_field(name=f"Хранилище ({len(storage_items)})", value="\n".join(storage_items) if storage_items else "пусто", inline=False)
        await interaction.followup.send(embed=embed, ephemeral=True)


class AdminEditModal(discord.ui.Modal, title="Изменить поле профиля"):
    user_id = discord.ui.TextInput(label="ID пользователя", required=True)
    field = discord.ui.TextInput(
        label="Поле",
        placeholder="coins / gems / grid_size / prestige_points",
        required=True,
    )
    value = discord.ui.TextInput(label="Новое значение", required=True)

    def __init__(self, author_id: int, target_id: int | None = None):
        super().__init__()
        self.author_id = author_id
        if target_id is not None:
            self.user_id.default = str(target_id)

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        try:
            uid = int(self.user_id.value)
        except ValueError:
            await interaction.followup.send("❌ ID должен быть числом.", ephemeral=True)
            return
        field = self.field.value.strip()
        if field not in (
            "coins", "gems", "catalysts", "grid_size",
            "storage_size", "prestige_points",
        ):
            await interaction.followup.send("❌ Неверное поле.", ephemeral=True)
            return
        try:
            parsed = int(self.value.value)
            if parsed < 0:
                raise ValueError
        except ValueError:
            await interaction.followup.send("❌ Неверное значение.", ephemeral=True)
            return
        max_value = {
            "grid_size": ADMIN_MAX_GRID,
            "storage_size": ADMIN_MAX_STORAGE,
            "prestige_points": ADMIN_MAX_PRESTIGE,
        }.get(field, ADMIN_MAX_RESOURCE)
        if parsed > max_value:
            await interaction.followup.send(
                f"❌ Максимум для `{field}`: **{max_value}**.",
                ephemeral=True,
            )
            return
        async with db_transaction():
            await bot.db.execute(
                f"UPDATE players SET {field} = ? WHERE user_id = ?",
                (parsed, uid),
            )
        await log_admin_action(
            self.author_id, uid, "edit",
            f"{field} = {parsed}"
        )
        await enforce_top_exclusion(
            interaction, uid, f"self_edit:{field}"
        )
        await interaction.followup.send(
            f"✅ `{field}` = **{parsed}** для <@{uid}>.",
            ephemeral=True,
        )


class AdminResetModal(discord.ui.Modal, title="Сбросить прогресс"):
    user_id = discord.ui.TextInput(label="ID пользователя", required=True)
    confirm = discord.ui.TextInput(label="Введите ДА для подтверждения", required=True)

    def __init__(self, author_id: int, target_id: int | None = None):
        super().__init__()
        self.author_id = author_id
        if target_id is not None:
            self.user_id.default = str(target_id)

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        if self.confirm.value.strip().upper() != "ДА":
            await interaction.followup.send("❌ Отменено.", ephemeral=True)
            return
        try:
            uid = int(self.user_id.value)
        except ValueError:
            await interaction.followup.send("❌ ID должен быть числом.", ephemeral=True)
            return
        for label, sql in (
            (
                "ордера на бирже",
                "SELECT 1 FROM market_orders WHERE user_id = ? "
                "AND status = 'active'",
            ),
            (
                "вклад в банке",
                "SELECT 1 FROM bank_deposits WHERE user_id = ?",
            ),
            (
                "кредит в банке",
                "SELECT 1 FROM bank_loans WHERE user_id = ? "
                "AND COALESCE(status, 'active') = 'active'",
            ),
            (
                "активные аукционы",
                "SELECT 1 FROM auctions WHERE seller_id = ? "
                "AND status = 'active'",
            ),
        ):
            async with bot.db.execute(sql, (uid,)) as c:
                if await c.fetchone():
                    return await interaction.followup.send(
                        f"❌ Сначала закрой {label} игрока.",
                        ephemeral=True,
                    )
        released_bids = 0
        async with db_transaction():
            # Убираем игрока из отряда и удаляем его приглашения.
            await detach_user_from_raid_party(uid)

            # Снимаем ставки на чужих лотах до обнуления баланса.
            released_bids, _refunded = await release_active_auction_bids(uid)

            # Возвращаем ставки по активным лотам и удаляем лоты игрока.
            async with bot.db.execute(
                "SELECT id, current_bidder, current_bid FROM auctions "
                "WHERE seller_id = ? AND status = 'active'",
                (uid,),
            ) as c:
                lots = await c.fetchall()
            for aid, bidder, bid in lots:
                if bidder and bid:
                    await bot.db.execute(
                        "UPDATE players SET coins = coins + ? WHERE user_id = ?",
                        (bid, bidder),
                    )
                await bot.db.execute(
                    "DELETE FROM auction_bids WHERE auction_id = ?", (aid,)
                )
                await bot.db.execute("DELETE FROM auctions WHERE id = ?", (aid,))

            await bot.db.execute("""
                UPDATE players SET
                    coins = ?, gems = 0, catalysts = 0,
                    grid_size = 9, storage_size = 36, income_bonus = 0.0,
                    total_crafts = 0, total_successes = 0,
                    total_coins_earned = 0, total_gems_earned = 0,
                    lifetime_production = 0,
                    last_collected = CURRENT_TIMESTAMP,
                    last_gem_collected = CURRENT_TIMESTAMP,
                    daily_quest_date = NULL,
                    daily_quest_progress = '{}',
                    daily_quest_claimed = '[]',
                    streak_days = 0,
                    last_daily = NULL,
                    title = 'Новичок',
                    active_pet = NULL,
                    last_tax_time = CURRENT_TIMESTAMP,
                    raid_wins = 0,
                    prestige_points = 0,
                    exchange_day = NULL,
                    exchange_coins_today = 0,
                    exchange_gems_today = 0
                WHERE user_id = ?
            """, (DEFAULT_START_COINS, uid))

            for table in (
                "inventory", "player_achievements", "player_upgrades", "craft_log",
                "craft_pity", "star_pity",
                "user_pets_v2", "autocollectors", "advent_progress", "advent_state",
                "bank_deposits", "bank_loans", "bank_history", "user_notifications",
                "player_quests", "user_cosmetics", "tax_log", "raid_cooldowns",
                "duel_cooldowns", "espionage_cooldowns", "player_collection",
                "season_progress", "season_xp_log", "market_orders",
                "onboarding_progress", "clan_applications", "giveaway_entries",
                "mailbox", "notification_fallback",
            ):
                await bot.db.execute(f"DELETE FROM {table} WHERE user_id = ?", (uid,))

            await bot.db.execute(
                "DELETE FROM duel_history WHERE winner_id = ? OR loser_id = ?",
                (uid, uid),
            )
            await bot.db.execute(
                "DELETE FROM raid_loot_log WHERE user_id = ?", (uid,)
            )

        onboarding_cache = getattr(bot, "_onboarding_complete_cache", None)
        if onboarding_cache is not None:
            onboarding_cache.discard(uid)
        _top_cache.clear()
        await log_admin_action(
            self.author_id, uid, "reset",
            f"coins = {DEFAULT_START_COINS}, inventory/quests/pets/cosmetics cleared",
        )
        reset_message = f"🗑️ Прогресс <@{uid}> сброшен."
        if released_bids:
            reset_message += (
                f"\n🏛️ Сняты активные ставки на аукционах: **{released_bids}**."
            )
        await interaction.followup.send(reset_message, ephemeral=True)


class AdminGiveItemModal(discord.ui.Modal, title="Выдать предмет"):
    user_id = discord.ui.TextInput(label="ID пользователя", required=True)
    item_id = discord.ui.TextInput(label="ID предмета", placeholder="basic_gen", required=True)
    quantity = discord.ui.TextInput(label="Количество", default="1", required=True)
    location = discord.ui.TextInput(label="Куда (profile/storage)", default="profile", required=True)

    def __init__(self, author_id: int, target_id: int | None = None):
        super().__init__()
        self.author_id = author_id
        if target_id is not None:
            self.user_id.default = str(target_id)

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        try:
            uid = int(self.user_id.value)
            qty = int(self.quantity.value)
            if qty < 1 or qty > 1000:
                raise ValueError
        except ValueError:
            await interaction.followup.send(
                "❌ ID и количество: 1–1000.", ephemeral=True
            )
            return
        loc = self.location.value.strip()
        if loc not in ("profile", "storage"):
            await interaction.followup.send("❌ Куда: `profile` или `storage`.", ephemeral=True)
            return
        item_id = self.item_id.value.strip()
        async with bot.db.execute("SELECT name, emoji FROM items WHERE id = ?", (item_id,)) as c:
            item = await c.fetchone()
        if not item:
            await interaction.followup.send("❌ Предмет не найден.", ephemeral=True)
            return
        name, emoji = item

        if loc == "profile":
            try:
                to_profile, to_storage, to_temp = await place_items(uid, item_id, qty)
            except ValueError as e:
                await interaction.followup.send(f"❌ {e}", ephemeral=True)
                return
            msg = f"✅ Выдано {qty}×{emoji} {name} <@{uid}>."
            if to_storage > 0 or to_temp > 0:
                msg += (
                    f"\n📦 {to_profile} на энергостанцию, {to_storage} в хранилище, "
                    f"{to_temp} во временное хранилище."
                )
        else:
            try:
                async with db_transaction():
                    storage_size = await get_storage_size(uid)
                    async with bot.db.execute(
                        "SELECT slot FROM inventory "
                        "WHERE user_id = ? AND location = 'storage'",
                        (uid,),
                    ) as c:
                        used = {r[0] for r in await c.fetchall()}
                    free = [s for s in range(storage_size) if s not in used]
                    if len(free) < qty:
                        raise ValueError(
                            f"В хранилище только {len(free)} слотов."
                        )
                    for i in range(qty):
                        await bot.db.execute(
                            "INSERT INTO inventory "
                            "(user_id, slot, item_id, location, stars) "
                            "VALUES (?, ?, ?, 'storage', 0)",
                            (uid, free[i], item_id)
                        )
                    await bot.db.execute(
                        "INSERT OR IGNORE INTO player_collection "
                        "(user_id, item_id) VALUES (?, ?)",
                        (uid, item_id),
                    )
            except ValueError as exc:
                return await interaction.followup.send(
                    f"❌ {exc}", ephemeral=True
                )
            msg = f"✅ Выдано {qty}×{emoji} {name} в хранилище <@{uid}>."

        await log_admin_action(
            self.author_id, uid, "give_item",
            f"{item_id} x{qty} -> {loc}",
        )
        await enforce_top_exclusion(
            interaction, uid, f"self_grant_item:{item_id}"
        )
        await sort_inventory(uid, "profile")
        await sort_inventory(uid, "storage")
        await interaction.followup.send(msg, ephemeral=True)


class AddGeneratorModal(discord.ui.Modal, title="Добавить генератор (шаг 1/2)"):
    id = discord.ui.TextInput(
        label="ID (латиницей)",
        placeholder="my_gen",
        max_length=32,
        required=True,
    )
    name = discord.ui.TextInput(
        label="Название",
        placeholder="Мой генератор",
        max_length=100,
        required=True,
    )
    price = discord.ui.TextInput(
        label="Цена", default="100", max_length=16, required=True
    )

    def __init__(self, author_id: int):
        super().__init__()
        self.author_id = author_id

    async def on_submit(self, interaction: discord.Interaction):
        if not await is_global_owner(interaction):
            await interaction.response.send_message(
                "❌ Контент может менять только владелец бота.",
                ephemeral=True,
            )
            return
        await interaction.response.defer(ephemeral=True)
        item_id = normalize_content_id(self.id.value)
        if not item_id:
            await interaction.followup.send(
                "❌ ID: латиница в нижнем регистре, цифры и `_` (2–32 символа).",
                ephemeral=True,
            )
            return
        price = parse_content_int(self.price.value)
        if price is None:
            await interaction.followup.send("❌ Цена: целое число от 0.", ephemeral=True)
            return
        name = normalize_content_name(self.name.value)
        if not name:
            await interaction.followup.send(
                "❌ Название: от 1 до 100 символов.", ephemeral=True
            )
            return
        async with bot.db.execute("SELECT 1 FROM items WHERE id = ?", (item_id,)) as c:
            if await c.fetchone():
                await interaction.followup.send(f"❌ ID `{item_id}` уже существует.", ephemeral=True)
                return

        embed = BotEmbed(
            title="Добавить генератор (шаг 2/2)",
            description=(
                f"ID: `{item_id}`\n"
                f"Название: **{name}**\n"
                f"Цена: 🪙 {price}\n\n"
                f"Заполни доходы и внешний вид:"
            ),
            color=0x3498db
        )
        await interaction.edit_original_response(
            embed=embed,
            view=AddGeneratorStep2View(self.author_id, item_id, name, price)
        )


