for _modal_name, _modal_value in list(globals().items()):
    if (
        _modal_name.startswith("Admin")
        and isinstance(_modal_value, type)
        and issubclass(_modal_value, discord.ui.Modal)
    ):
        guard_admin_modal(
            _modal_value,
            lambda interaction: is_global_owner(interaction),
            "❌ Глобальные действия доступны только владельцу бота.",
        )


# ============================================================
#  🚀 ЗАПУСК
# ============================================================

if __name__ == "__main__":  # pragma: no cover
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
    )
    token = os.getenv("DISCORD_BOT_TOKEN")
    if not token:
        raise SystemExit(
            "DISCORD_BOT_TOKEN не задан. Добавь переменную окружения "
            "или настрой .env на хостинге."
        )

    def _handle_sigterm(*_args):
        try:
            asyncio.get_event_loop().create_task(bot.close())
        except Exception:
            log.exception("Не удалось запустить graceful shutdown по SIGTERM")

    try:
        signal.signal(signal.SIGTERM, _handle_sigterm)
    except (ValueError, OSError):
        pass

    bot.run(token)
